const response = $input.first().json;
const contents = response.output?.filter(item => item.type === 'message').flatMap(item => item.content) ?? [];
const texts = contents.filter(item => item.type === 'output_text');
if (response.status !== 'completed' || texts.length !== 1 || contents.some(item => item.type === 'refusal')) {
  throw new Error('The model did not produce one complete proposal.');
}
let proposal = texts[0].text;
if (typeof proposal === 'string') {
  try {
    proposal = JSON.parse(proposal);
  } catch {
    throw new Error('The model returned invalid JSON.');
  }
}
if (!proposal || typeof proposal !== 'object' || Array.isArray(proposal)) {
  throw new Error('The model returned an invalid proposal.');
}
return [{ json: proposal }];
